/**
 * `data/items/itemIndex.json` as generated by `scripts/wow_item_pages/index.py`:
 * one row per item, quality / slot / type / change as positions in the header lists
 * (`itemType` -1 = none). Decoded by `lib/itemBrowser/decodeItemIndex.ts`.
 */
export interface ItemIndexFile {
  source: string;
  clientBuild: string;
  attribution: string;
  columns: readonly string[];
  qualities: readonly string[];
  slots: readonly string[];
  itemTypes: readonly string[];
  changeKinds: readonly string[];
  items: readonly (readonly (string | number)[])[];
}
